        { q: "Why is the boundary between treatment and enhancement important?", options: ["Because it determines what is legally permitted", "Because it changes the price", "Because scientists prefer it", "Because patients ask for it"], answer: 0 },
        { q: "Which editing receives less public attention but affects more people?", options: ["Germline editing", "Crop editing", "Blood disorder therapy", "Organ printing"], answer: 1 }
